        if (!doAsFly) timer++;
        if (timer > delay.get()) {
            timer = 0;
            doAsFly = true;
            stage = 0;
            move();
        }
        if (mc.gameSettings.keyBindJump.isKeyDown()) {
            mc.timer.timerSpeed = (BindSlowSpeed.get() / 10);
        }else{
            mc.timer.timerSpeed = 1f;
        }
        if (stage >= 1) {
            doAsFly = false;
            if (packets.size() > 0) {
                for (Packet<?> packet : packets) {
                    mc.thePlayer.sendQueue.addToSendQueue(packet);
                    packets.remove(packet);
                }
            }
        }
    }

