            targetPitch = 94;
        } else {
            targetYaw = mc.thePlayer.rotationYaw - 180;
            targetPitch = 90;
        }

        startY = mc.thePlayer.posY;
        targetBlock = null;
        placePossibilities.clear();

        if (randomiseRotationSpeedOnEnable.isEnabled()) {
            rotationSpeed.setValue(50 + (85 - 50) * Math.random());
