        settings.put(INVCLEANER, new Setting<>(INVCLEANER, true, "Cleans your inventory for you."));
		settings.put(MODE, new Setting<>(MODE, new Options("Mode", "Basic",new String[] {"Basic", "OpenInv"}), "InvManager method."));
