            		getBestAxe(axeSlot);
            	}
            	if(timer.check(delay) && (Boolean) settings.get(INVCLEANER).getValue())
                for (int i = 9; i < 45; i++) {
                    if (mc.thePlayer.inventoryContainer.getSlot(i).getHasStack()) {
                        ItemStack is = mc.thePlayer.inventoryContainer.getSlot(i).getStack();
                        if(shouldDrop(is, i)){
