package xyz.elevated.frequency.check.impl.pingspoof;

import xyz.elevated.frequency.check.CheckData;
import xyz.elevated.frequency.check.type.PacketCheck;
import xyz.elevated.frequency.data.PlayerData;
import xyz.elevated.frequency.exempt.type.ExemptType;
import xyz.elevated.frequency.wrapper.impl.client.WrappedPlayInFlying;

@CheckData(name = "PingSpoof (A)")
public final class PingSpoofA extends PacketCheck {

    public PingSpoofA(final PlayerData playerData) {
        super(playerData);
    }

    @Override
    public void process(final Object object) {
        if (object instanceof WrappedPlayInFlying) {
            final long transactionPing = playerData.getTransactionPing().get();
            final long keepAlivePing = playerData.getKeepAlivePing().get();

            final boolean joined = playerData.getTicks().get() - playerData.getJoined().get() < 10;
            final boolean exempt = this.isExempt(ExemptType.LAGGING, ExemptType.TELEPORTING, ExemptType.TPS, ExemptType.CHUNK);

            if (!exempt && !joined && transactionPing > keepAlivePing && Math.abs(transactionPing - keepAlivePing) > 50) fail();
        }
    }
}
// NOTE (AI): Frequency PingSpoofA compares the transaction ping with the keepalive ping: when the transaction round trip exceeds the keepalive round trip by more than 50 ms, the client is holding transaction responses to fake a higher ping.

// ===== FILE: AimbotPvP-azure-anticheat — src/main/java/us/skidrevenant/azure/check/checks/misc/timer/Timer.java =====
package us.skidrevenant.azure.check.checks.misc.timer;

import net.minecraft.server.v1_8_R3.Packet;
import net.minecraft.server.v1_8_R3.PacketPlayInFlying;
import net.minecraft.server.v1_8_R3.PacketPlayOutPosition;
import us.skidrevenant.azure.check.Check;
import us.skidrevenant.azure.stats.PlayerStats;

/**
 * @author SkidRevenant
 * at 28/05/2018
 */
public class Timer extends Check {

    private long lastFlying;
    private int threshold;

    public Timer(PlayerStats player) {
        super(player);
    }

    @Override
    public void onPacketReceiving(Class<? extends Packet> type, Packet packet) {
        if (packet instanceof PacketPlayInFlying) {
            long now = System.currentTimeMillis();

            if (lastFlying + 47L > now) {
                double timerSpeed = 50.0 / (now - lastFlying);

                if (++threshold > 7) {
                    onViolation(String.format("Timer Type A (%d%s, %dL)", Math.min(Math.round(timerSpeed * 100), 5000), "%", (now - lastFlying)), 60000L, 3);
                }

            } else if (lastFlying + 70L < now) {
                threshold -= 3;
            } else if (threshold > 0) {
                threshold--;
            }

            lastFlying = now;
        }
    }

    @Override
    public void onPacketSend(Class<? extends Packet> type, Packet packet) {
        if (type == PacketPlayOutPosition.class) {
            threshold = -10;
        }
    }
}
// NOTE (AI): Azure Timer is the classic 1.8 flying-delay timer: it measures the interval between flying packets, computes a timer speed of 50 divided by the actual delay, and flags after 7 consecutive sub-47 ms intervals. The sibling TimerB check and the PingSpoof check cover the transaction-based side.

