public class LongJump extends Module {

	public LongJump() {
		super("Long Jump", Keyboard.KEY_NONE, Category.MOVEMENT);
	}


	public void onEnable() {

        PlayerCapabilities playerCapabilities = new PlayerCapabilities();
        playerCapabilities.isFlying = true;
        playerCapabilities.allowFlying = true;
        playerCapabilities.setFlySpeed((float) ((Math.random() * (9.0 - 0.1)) + 0.1));
        playerCapabilities.isCreativeMode = true;
        mc.getNetHandler().getNetworkManager().sendPacketNoEvent(new C13PacketPlayerAbilities(playerCapabilities));

	}

	public void onDisable() {

	}

	public static boolean jumped = false;
	public static Timer timer = new Timer();


	public void onEvent(Event e) {

		if (e instanceof EventUpdate && e.isPre()) {
			this.additionalInformation = "Hypixel";
		}

		if (e instanceof EventMotion) {

			if (e.isPost()) {

				if (jumped && mc.thePlayer.onGround) {
					this.toggle();
					jumped = false;
					return;
				}

				mc.gameSettings.keyBindJump.pressed = false;

                if (MovementUtils.isOnGround(0.000001)) {

                	MovementUtils.strafe((float) Math.sqrt(mc.thePlayer.motionX * mc.thePlayer.motionX + mc.thePlayer.motionZ * mc.thePlayer.motionZ) + 1.25f);
                    mc.thePlayer.jump();
                    e.setCanceled(true);
                    jumped = true;

                }

                mc.thePlayer.setSprinting(true);

			}

		}

	}


}
// NOTE (AI): LongJump's onEnable forges a PlayerCapabilities with isFlying, allowFlying, isCreativeMode and a random flySpeed between 0.1 and 9.0, then sends it via sendPacketNoEvent. The vanilla server ignores allowFlying, creativeMode and flySpeed from C13 and only ANDs the isFlying bit against its own allowFlying, so this is a client-side state declaration for the movement code, with the packet doubling as a desync probe against servers that do read abilities.

