        open = mc.currentScreen instanceof GuiChatOF;
        lineHeight = chatFont.height();

        float expandedHeight = Math.min((open ? openHeight : closedHeight).getValue().intValue(), lineHeight * lineCount + (lineCount == 0 ? 0 : 7));

