    public void onStrafe(final StrafeEvent event) {
        if (mineland.isEnabled()) {
            PacketUtil.sendPacket(new C18PacketSpectate(UUID.randomUUID()));
        }
    }

    @Override
    public void onWorldChanged(final WorldChangedEvent event) {
    }

}
// NOTE (AI): The C18 hits are in three disabler modes. verusOld sends C18 with UUID.randomUUID() every tick alongside C0C input; c18/shartemis modes send C18 with the player's own UUID; mineland sends C18 with a random UUID from onStrafe. The random-UUID forms force the server's handleSpectate to search every world for an entity that does not exist; the own-UUID form targets the spectator reset path. All three are sendPacketWithoutEvent, so they never re-enter the event bus.

