            if (em.isPre()) {
                if (mc.thePlayer.ticksExisted <= 1) {
                    erisium = false;
                }
                if (mode.equalsIgnoreCase("ViperMC")) {
                    if (timer.delay(3000)) {
                        em.setY(mc.thePlayer.posY + 0.4);
