public class Ambiance extends Module {

	public Ambiance() {
		super("Ambience", 0, Module.Category.RENDER);
		this.addModes("Morning", "Night");
	}

	@Handler
	public Consumer<PacketInEvent> eventConsumer0 = (event) -> {
		if (event.getPacket() instanceof S03PacketTimeUpdate) {
			event.cancel();
		}
	};

	@Handler
	public Consumer<UpdateEvent> eventConsumer1 = (event) -> {
		mc.theWorld.getWorldInfo().setWorldTime(this.isMode("Morning") ? 0 : 20000);
	};

}

// NOTE (AI): The class is Ambiance but the module registers under the name 'Ambience'.
// The two modes map to worldTime 0 (dawn) and 20000 (night, 24000 - 4000). Cancelling on
// PacketInEvent and writing on UpdateEvent means the client clock survives every server
// correction; because no packet reports time back, the server cannot observe the desync.
// This is the smallest complete example of the cancel-and-pin pattern in the corpus.

