import net.minecraft.network.play.client.C09PacketHeldItemChange;
import net.minecraft.network.play.server.S09PacketHeldItemChange;

/**
 * @author Gavin
 * @since 2.0.0
 */
public class InventoryManager {

  /**
   * The {@link Minecraft} game instance
   */
  private final Minecraft mc = Minecraft.getMinecraft();

  private int slot = -1;

  public InventoryManager() {
    November.bus().subscribe(this);
  }

  @Subscribe
  private final Listener<EventPacket.Out> packetOut = event -> {
    if (event.get() instanceof C09PacketHeldItemChange packet) {
      slot = packet.getSlotId();
    }
  };

  @Subscribe
  private final Listener<EventPacket.In> packetIn = event -> {
    if (event.get() instanceof S09PacketHeldItemChange packet) {
      slot = packet.getHeldItemHotbarIndex();
    }
  };

  public int slot() {
    if (slot == -1) return slot = mc.thePlayer.inventory.currentItem;
    return slot;
  }

  public void sync() {
    if (slot != mc.thePlayer.inventory.currentItem) {
      mc.thePlayer.sendQueue.addToSendQueue(
        new C09PacketHeldItemChange(mc.thePlayer.inventory.currentItem)
      );
    }
  }

  public ItemStack itemStack() {
    return mc.thePlayer.inventory.getStackInSlot(slot());
  }
}


// NOTE (AI): The manager listens to both directions of the slot exchange: C09 records the client's request, S09 records the server's confirmation. Because the server bounds-checks and applies S09 to inventory.currentItem, the tracked slot is the server's view, which is what aura/autoclicker logic wants when it must not desync the hotbar. sync() is the silent-switch primitive: it only fires C09 when the local and tracked slots disagree.

