            PacketUtil.sendPacketWithoutEvent(new C07PacketPlayerDigging(C07PacketPlayerDigging.Action.STOP_DESTROY_BLOCK, blockPos, EnumFacing.NORTH));

            if (swing.isEnabled())
                mc.thePlayer.swingItem();
        } else {
            for (double x = -range; x < range; x++) {
