import dev.rise.util.math.TimeUtil;
import net.minecraft.network.Packet;
import net.minecraft.network.play.server.S0BPacketAnimation;

@CheckInfo(name = "AutoClicker", type = "A", description = "Detects clicking too fast")
public final class AutoClickerA extends Check {

    private final TimeUtil timer = new TimeUtil();
    private int swings;

    public AutoClickerA(final PlayerData data) {
        super(data);
    }

    @Override
    public void handle(final Packet<?> packet) {
        if (packet instanceof S0BPacketAnimation) {
            final S0BPacketAnimation wrapper = (S0BPacketAnimation) packet;
            if (wrapper.getEntityID() == data.getPlayer().getEntityId())
                swings++;
        }

        if (PacketUtil.isRelMove(packet)) {
            if (swings > 3) {
                if (getBuffer() >= 3)
                    fail();

                increaseBuffer();
                timer.reset();
            } else if (timer.hasReached(1000L)) {
                decreaseBuffer();
                timer.reset();
            }

            swings = 0;
        }
    }
}
// NOTE (AI): Not a cheat module: this is Rise 5.99's own client-side anticheat. The check counts S0B swing packets whose entity id is the local player and compares them against relative-move packets: more than 3 swings per movement packet with a warmed buffer fails the AutoClicker check. It demonstrates that S0B is the swing ground truth the whole ecosystem, cheats and anti-cheats alike, keys on. KeepSprintA is the sibling check in the same package, coupling swings to sprint state to catch keepsprint cheats.

